/bin/bash -lc "python3 - <<'PY'
import cv2, numpy as np
from PIL import Image
im=np.array(Image.open('first_frame.png'))
# actual ROI saturation mask with object signature y45:103 x70:125
for tag,(x0,x1,y0,y1) in {'obj':(68,127,42,105),'ref':(158,218,42,100)}.items():
 r=im[y0:y1,x0:x1]; mx=r.max(2); mn=r.min(2)
 sat=(mx-mn)
 if tag=='obj': m=((sat>15)&((r[:,:,2]>r[:,:,0]+8)|(r[:,:,0]>r[:,:,2]+8))).astype(np.uint8)
 else: m=((sat>12)&((r[:,:,2]>r[:,:,0]+6)|(r[:,:,0]>r[:,:,2]+6))).astype(np.uint8)
 m=cv2.morphologyEx(m,cv2.MORPH_CLOSE,np.ones((5,5),np.uint8));
 n,l,st,c=cv2.connectedComponentsWithStats(m)
 i=1+np.argmax(st[1:,4]); mm=(l==i).astype(np.uint8)
 # row runs
 print(tag, st[i].tolist())
 for y in range(mm.shape[0]):
  xs=np.where(mm[y])[0]
  if len(xs): print(y+y0, (xs.min()+x0,xs.max()+x0),len(xs))
 cv2.imwrite('.tmp/'+tag+'mask.png',mm*255)
PY"
